from collections import defaultdict

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent):
        visited[node] = True
        disc_time[node] = low_time[node] = time
        time += 1

        children = 0
        for neighbor in graph[node]:
            if not visited[neighbor]:
                children += 1
                dfs(neighbor, node)
                low_time[node] = min(low_time[node], low_time[neighbor])

                if parent != -1 and low_time[neighbor] >= disc_time[node]:
                    bridges.append((node, neighbor))

            elif neighbor != parent:
                low_time[node] = min(low_time[node], disc_time[neighbor])

    visited = [False] * n
    disc_time = [float('inf')] * n
    low_time = [float('inf')] * n
    time = 0
    bridges = []

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    return bridges

