def first_unique_char(s: str) -> int:
    char_count = {}

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first unique character
    for i, char in enumerate(s):
        if char_count[char] == 1:
            return i

    # No unique character found
    return -1
