def binary_to_decimal(b: str) -> int:
    decimal_value = 0
    power_of_2 = 0

    # Reverse the binary string to process from least significant bit to most significant bit
    b = b[::-1]

    for digit in b:
        if digit == '1':
            decimal_value += 2 ** power_of_2
        power_of_2 += 1

    return decimal_value

def binary_to_decimal(b: str) -> int:
