        power_of_2 += 1

    return decimal_value

def binary_to_decimal(b: str) -> int:
    decimal_value = 0
    power_of_2 = 1

    # Iterate over each character in the binary string from right to left
    for char in reversed(b):
        if char == '1':
            decimal_value += power_of_2
        power_of_2 *= 2

    return decimal_value

