    return bin(abs(n))[2:].lstrip('0')

def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'

    # Handle negative numbers by converting them to positive, performing the conversion,
    # and then adding the '-' back at the end.
    if n < 0:
        n = -n

    binary_representation = ''
    while n > 0:
        remainder = n % 2
        binary_representation = str(remainder) + binary_representation
        n //= 2

    return binary_representation

