def count_inversions(nums: list[int]) -> int:
    if not nums:
        return 0

    def merge_sort(arr):
        if len(arr) <= 1:
            return arr

        mid = len(arr) // 2
        left_half = merge_sort(arr[:mid])
        right_half = merge_sort(arr[mid:])

        i = j = k = 0

        while i < len(left_half) and j < len(right_half):
            if left_half[i] <= right_half[j]:
                arr[k] = left_half[i]
                i += 1
            else:
                arr[k] = right_half[j]
                j += 1
                k += 1
                # Count inversion for each element in right half that is smaller than current element in left half
                count += len(left_half) - i

        while i < len(left_half):
            arr[k] = left_half[i]
            i += 1
            k += 1

        while j < len(right_half):
            arr[k] = right_half[j]
            j += 1
            k += 1

        return arr

    sorted_nums = merge_sort(nums)
    return sorted_nums.count(0)
