def compute_lcm(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    else:
        # Calculate the greatest common divisor (GCD)
        gcd = abs(a * b) // math.gcd(a, b)
        # Compute the least common multiple (LCM) using the formula LCM(a, b) = |a*b| / GCD(a, b)
        lcm = abs(a * b) // gcd
        return lcm

