import subprocess

def compress_file(path: str) -> str:
    # Run gzip command on the file
    result = subprocess.run(['gzip', path], capture_output=True, text=True)

    # Check if the command was successful
    if result.returncode == 0:
        return f"{path}.gz"
    else:
        raise Exception(f"Failed to compress file {path}: {result.stderr}")

