from typing import List

def longest_consecutive_streak(items: List[int]) -> int:
    if not items:
        return 0

    items.sort()
    max_streak = 1
    current_streak = 1

    for i in range(1, len(items)):
        if items[i] == items[i - 1] + 1:
            current_streak += 1
        else:
            max_streak = max(max_streak, current_streak)
            current_streak = 1

    return max(max_streak, current_streak)
