def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])
    i, j = 0, 0
    direction = 1

    while True:
        # Add current element to the result
        result.append(matrix[i][j])

        # Move to the next position based on the current direction
        if direction == 1:
            if j + 1 < cols:
                j += 1
            else:
                direction = -1
                i += 1
        elif direction == -1:
            if j - 1 >= 0:
                j -= 1
            else:
                direction = 1
                i += 1

        # If we reach the end of the matrix, break the loop
        if i >= rows or j >= cols:
            break

    return result
