def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append('-' if remainder < 0 else '+' if remainder > 0 else '0')
        n += remainder * (-2 ** len(digits))

    return ''.join(reversed(digits))
