def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append('-' if remainder == -1 else '+' if remainder == 2 else '0')
        n = abs(n // 3)

    # Reverse the list to get the correct order and remove trailing zeros
    digits.reverse()
    while digits and digits[-1] == '0':
        digits.pop()

    return ''.join(digits[::-1])
