from collections import deque

def height_queue_reconstruction(people):
    # Sort the people by their height in descending order
    people.sort(key=lambda x: -x[0])

    # Initialize the result queue with the first person
    result = deque([people.pop()])

    while people:
        # For each person, find the position they should occupy in the result queue
        for i in range(len(result)):
            if result[i][0] >= people[-1][0]:
                result.insert(i, people.pop())
                break

    return list(result)
