import re

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Expression cannot be empty")

    # Remove spaces from the expression
    expression = expression.replace(" ", "")

    # Check for balanced parentheses
    if "(" in expression or ")" in expression:
        raise ValueError("Unbalanced parentheses")

    # Define the regular expression pattern for tokens
    token_pattern = r"(\d+(\.\d+)?)|[-+\*/]**|[\(\)]"

    # Find all tokens in the expression
    tokens = re.findall(token_pattern, expression)

    # Evaluate the expression using a stack-based approach
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(float(token))
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack[-1] != '(':
                operator = stack.pop()
                operand2 = stack.pop()
                operand1 = stack.pop()
                result = apply_operator(operator, operand1, operand2)
                stack.append(result)
            stack.pop()  # Pop the '('
        else:
            operator = token
            while stack and has_precedence(stack[-1], operator):
                operand2 = stack.pop()
                operand1 = stack.pop()
                result = apply_operator(operator, operand1, operand2)
                stack.append(result)
            stack.append(operator)

    # Apply any remaining operators on the stack
    while stack:
        operator = stack.pop()
        operand2 = stack.pop()
        operand1 = stack.pop()
        result = apply_operator(operator, operand1, operand2)
        stack.append(result)

    return stack[0]

