def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        result = [[0] * len(b[0]) for _ in range(len(a))]
        for i in range(len(a)):
            for j in range(len(b[0])):
                for k in range(len(b)):
                    result[i][j] += (a[i][k] * b[k][j]) % mod
        return result

    def matrix_exponentiation(base: list[list[int]], exp: int, mod: int) -> list[list[int]]:
        if exp == 0:
            return [[1] * len(base[0]) for _ in range(len(base))]
        elif exp % 2 == 0:
            half_exp = matrix_exponentiation(base, exp // 2, mod)
            return multiply_matrices(half_exp, half_exp, mod)
        else:
            return multiply_matrices(base, matrix_exponentiation(base, exp - 1, mod), mod)

    return matrix_exponentiation(matrix, exp, mod)
