def shortest_path_one_break(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the starting point S and ending point E
    start = None
    end = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1  # Starting or ending point not found

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = [(start[0], start[1], 0)]  # Queue to store coordinates and steps taken
    visited = set()

    while queue:
        x, y, steps = queue.pop(0)

        if (x, y) == end:
            return steps

        if (x, y) in visited:
            continue

        visited.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                queue.append((nx, ny, steps + 1))

    return -1  # No path found
