from math import gcd

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Extract moduli and remainders
    moduli = [mod for _, mod in congruences]
    remainders = [rem for rem, _ in congruences]

    # Calculate the product of all moduli
    L = 1
    for m in moduli:
        L *= m

    # Calculate the partial products for each modulus
    partial_products = []
    for i in range(len(moduli)):
        partial_product = 1
        for j in range(len(moduli)):
            if i != j:
                partial_product *= moduli[j] // gcd(moduli[i], moduli[j])
        partial_products.append(partial_product)

    # Solve the system of linear equations using the Chinese Remainder Theorem
    x = 0
    for i in range(len(moduli)):
        x += remainders[i] * partial_products[i] * pow(L // partial_products[i], -1, moduli[i])

    # Ensure the result is within the range [0, L-1]
    x %= L

    return (x, L)
