from itertools import combinations

def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def backtrack(start, current):
        if sum(current) == k:
            result.append(sorted(current))
            return
        for i in range(start, len(nums)):
            if nums[i] > k - sum(current):  # Early pruning
                break
            backtrack(i + 1, current + [nums[i]])

    result = []
    backtrack(0, [])
    return sorted(result)
