import operator

def evaluate_expression(expression: str) -> float:
    # Define the mapping of operators to their corresponding functions
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow,
        '-': lambda x: -x
    }

    def apply_operator(operators, values):
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        return ops[op](left, right)

    def parse_expression(expr):
        tokens = expr.replace(' ', '').split()
        values = []
        operators = []

        for token in tokens:
            if token.isdigit():
                values.append(float(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    values.append(apply_operator(operators, values))
                operators.pop()  # Remove the '('
            elif token in ops:
                while operators and operators[-1] != '(' and ops[token].precedence >= ops[operators[-1]].precedence:
                    values.append(apply_operator(operators, values))
                operators.append((token, ops[token]))

        while operators:
            values.append(apply_operator(operators, values))

        return values[0]

    try:
        return parse_expression(expression)
    except ZeroDivisionError:
        raise ValueError("Division by zero")
    except ValueError:
        raise ValueError("Invalid expression")

# Example usage
