    def apply_operator(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            return a / b
        elif op == '**':
            return a ** b
        elif op == '-':
            return -a

    def parse_expression(expr):
        tokens = expr.replace(' ', '').split()
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token in "+-*/**":
                while stack and stack[-1] != '(' and (operator.precedence[token] <= operator.precedence[stack[-1]] or (operator.precedence[token] < operator.precedence[stack[-1]] and operator.associativity[token] == 'left')):
                    right = stack.pop()
                    left = stack.pop()
                    result = apply_operator(stack.pop(), left, right)
                    stack.append(result)
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    right = stack.pop()
                    left = stack.pop()
                    result = apply_operator(stack.pop(), left, right)
                    stack.append(result)
                stack.pop()  # Remove the '(' from the stack

        while stack:
            right = stack.pop()
            left = stack.pop()
            result = apply_operator(stack.pop(), left, right)
            stack.append(result)

        return stack[0]

    try:
        return parse_expression(expression)
    except ValueError as e:
        raise ValueError(f"Invalid expression: {e}")
    except ZeroDivisionError as e:
        raise ZeroDivisionError(f"Division by zero: {e}")

# Example usage
print(evaluate_expression("3 + 4 * (2 - 1)"))  # Output: 9.0
print(evaluate_expression("10 / 2"))  # Output: 5.0
print(evaluate_expression("(3 + 4) * 2"))  # Output: 14.0
try:
    print(evaluate_expression("10 / 0"))  # Raises ZeroDivisionError
except ZeroDivisionError as e:
    print(e)
try:
    print(evaluate_expression("invalid expression"))  # Raises ValueError
except ValueError as e:
    print(e)
