from itertools import combinations

def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    # Sort the input list to handle duplicates and make the search more efficient
    nums.sort()

    # Initialize an empty list to store the result
    result = []

    # Iterate over all possible lengths of subsets
    for r in range(len(nums) + 1):
        # Generate all combinations of the current length
        for combo in combinations(nums, r):
            # Check if the sum of the combination equals k
            if sum(combo) == k:
                # Add the combination to the result list after sorting it
                result.append(sorted(list(combo)))

    # Return the sorted result list
    return sorted(result)

