def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []

    for operation in operations:
        if operation[0] == "put":
            if capacity > 0:
                if operation[1] in cache:
                    cache.move_to_end(operation[1])
                elif len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[operation[1]] = operation[2]
        elif operation[0] == "get":
            if operation[1] in cache:
                cache.move_to_end(operation[1])
                results.append(cache[operation[1]])
            else:
                results.append(None)

    keys = list(cache.keys())
    return results, keys
