def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(board: List[List[bool]], row: int, col: int) -> bool:
        # Check this row on left side
        for i in range(col):
            if board[row][i]:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j]:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j]:
                return False

        return True

    def backtrack(board: List[List[bool]], col: int) -> int:
        if col >= n:
            return 1

        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = True
                count += backtrack(board, col + 1)
                board[i][col] = False

        return count

    board = [[False] * n for _ in range(n)]
    return backtrack(board, 0)
