        inverses.append(inverse)

    # Solve the system of linear congruences using the Chinese Remainder Theorem
    x = 0
    for i in range(len(moduli)):
        x += remainders[i] * inverses[i] * product_moduli // moduli[i]

    # Normalize the result to ensure it is within the range [0, L)
    x %= product_moduli

