        elif op == '*':
            return x * y
        elif op == '/':
            if y == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            return x / y
        elif op == '**':
            return x ** y
        elif op == '-':
            return -x
        else:
            raise ValueError(f"Invalid operator: {op}")

