def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0])
    new_grid = [[0 for _ in range(cols)] for _ in range(rows)]

    while True:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] > 3:
                    new_grid[r][c] -= 4
                    if r > 0:
                        new_grid[r-1][c] += 1
                    if r < rows - 1:
                        new_grid[r+1][c] += 1
                    if c > 0:
                        new_grid[r][c-1] += 1
                    if c < cols - 1:
                        new_grid[r][c+1] += 1
                    changed = True

        if not changed:
            break

    return new_grid
