            if start_date.strftime("%A") not in ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]:
                continue
            if start_date.strftime("%Y-%m-%d") in holidays:
                continue
            n -= 1

    return start_date.strftime("%Y-%m-%d")

