from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    sizes.sort(reverse=True)
    bins = []
    current_capacity = 0

    for size in sizes:
        if size > capacity:
            raise ValueError("Element is too large")

        if current_capacity + size <= capacity:
            current_capacity += size
            bins.append([size])
        else:
            bins[-1].append(size)

    return bins
