def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Invalid input")

    def to_decimal(num_str, base):
        return sum(int(digit, base) * (base ** idx) for idx, digit in enumerate(reversed(num_str)))

    def from_decimal(decimal_val, target_base):
        if decimal_val == 0:
            return "0"
        digits = []
        while decimal_val > 0:
            digits.append(chr((decimal_val % target_base) + ord('0')))
            decimal_val //= target_base
        return ''.join(digits[::-1])

    if number[0] == '-':
        number = number[1:]
        result = '-' + from_decimal(to_decimal(number, from_base), to_base)
    else:
        result = from_decimal(to_decimal(number, from_base), to_base)

    return result
