import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check if target is a site-relative path starting with a single forward slash
    if target.startswith('/') and '/' not in target[1:]:
        return True

    # Check if target starts with http:// or https:// and host matches
    if re.match(r'^https?://[^/]+$', target):
        host_match = re.search(r'^(?:http|https):\/\/([^/]+)', target)
        if host_match and host.lower() == host_match.group(1).lower():
            return True

    # If target contains any invalid characters, return False
    if re.search(r'[^\w\/\s]', target):
        return False

    return False
