import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check if the URL starts with http or https
    if not url.lower().startswith(('http://', 'https://')):
        return False

    # Extract the host name from the URL
    host = re.search(r'(?<=:\/\/)([^/:]+)', url)
    if not host:
        return False

    # Convert the host name to lowercase and remove trailing dots
    host = host.group(1).lower().rstrip('.')

    # Check if the host matches any allowed host
    for allowed_host in allowed_hosts:
        if allowed_host.lower() == host:
            return True

    return False

