    if not results:
        return []

    # Initialize a dictionary to store the total points and goals for each team
    team_scores = {}
    for home, away, h_goals, a_goals in results:
        if home not in team_scores:
            team_scores[home] = {'total_points': 0, 'goals_for': 0, 'goals_against': 0}
        if away not in team_scores:
            team_scores[away] = {'total_points': 0, 'goals_for': 0, 'goals_against': 0}

        # Update the scores based on the outcome of the match
        if h_goals > a_goals:
            team_scores[home]['total_points'] += 3
            team_scores[away]['goals_against'] += a_goals
        elif h_goals < a_goals:
            team_scores[away]['total_points'] += 3
            team_scores[home]['goals_against'] += h_goals
        else:
            team_scores[home]['total_points'] += 1
            team_scores[away]['total_points'] += 1
            team_scores[home]['goals_for'] += h_goals
            team_scores[away]['goals_for'] += a_goals

    # Calculate the goal difference and goals scored for each team
