from jinja2 import Template

def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    if not recipients:
        return []

    rendered_texts = []
    for recipient in recipients:
        # Create a new context for each recipient
        context = {key: value for key, value in recipient.items()}

        # Render the template using the current context
        rendered_text = Template(template).render(context)

        # Append the rendered text to the list
        rendered_texts.append(rendered_text)

    return rendered_texts

