from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find starting and ending positions
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No start or end position found

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def dfs(x, y, count):
        nonlocal end_pos

        if (x, y) == end_pos:
            return count

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny):
                result = dfs(nx, ny, count + 1)
                if result != -1:
                    return result

        return -1

    return dfs(start_pos[0], start_pos[1], 0)
