from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    def is_safe(row: int, col: int) -> bool:
        for r, c in blocked:
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row: int, count: int) -> int:
        if row == n:
            return count + 1

        for col in range(n):
            if is_safe(row, col):
                blocked.append((row, col))
                count = backtrack(row + 1, count)
                blocked.pop()

        return count

    return backtrack(0, 0)
