import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field):
        if field.startswith('"'):
            return parse_quoted_field(field)
        else:
            return [field]

    def parse_quoted_field(field):
        result = []
        i = 0
        while i < len(field):
            if field[i] == '"':
                j = i + 1
                while j < len(field) and field[j] != '"':
                    j += 1
                if j == len(field):
                    raise ValueError("Unmatched opening quote")
                result.append(parse_field(field[i+1:j]))
                i = j + 1
            elif field[i] == ',':
                result.append(parse_field(field[i+1:]))
                i += 1
            elif field[i] == '\n':
                break
            else:
                result.append(field[i])
                i += 1
        return result

    records = []
    current_record = []
    for line in text.split('\n'):
        if line.strip() == '':
            if current_record:
                records.append(current_record)
                current_record = []
        else:
            fields = line.split(',')
            current_record.extend(parse_field(field))
    if current_record:
        records.append(current_record)

    return records
