import re

def is_public_ip(ip_str: str) -> bool:
    # Regular expression for validating an IPv4 address
    ipv4_pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9])$'

    # Regular expression for validating an IPv6 address
    ipv6_pattern = r'^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$'

    # Check if the IP string matches either pattern
    if re.match(ipv4_pattern, ip_str):
        return True  # IPv4 address
    elif re.match(ipv6_pattern, ip_str):
        return True  # IPv6 address

    # Check if the IP string is a valid IPv4 address with embedded IPv4 part
    if '.' in ip_str:
        parts = ip_str.split('.')
        if len(parts) == 4:
            for part in parts:
                if not part.isdigit() or int(part) < 0 or int(part) > 255:
                    return False
            return True  # Valid IPv4 address with embedded IPv4 part

    # Check if the IP string is a valid IPv6 address with embedded IPv4 part
    if ':' in ip_str:
        parts = ip_str.split(':')
        if len(parts) >= 8:
            for part in parts:
                if not part.isdigit() and not all(c in '0123456789abcdefABCDEF' for c in part):
                    return False
            return True  # Valid IPv6 address with embedded IPv4 part

    return False  # Not a valid IP address
