import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.lower().startswith('https://'):
        return False

    # Remove user@ or user:password@
    url = re.sub(r'(?i)(?:user@[a-zA-Z0-9.-]+|user:[a-zA-Z0-9.-]+@)', '', url)

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\\s\0-\x1f]', url):
        return False

    # Split the host into labels
    labels = url.split('.')

    # Check if there are fewer than two labels or more than three labels
    if len(labels) < 2 or len(labels) > 3:
        return False

    # Check if any label contains invalid characters
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the last label ends with .localhost
    if labels[-1].lower() == '.localhost':
        return False

    # Check if the host is localhost
    if url.lower() == 'localhost':
        return False

    # Check if the port is absent or is 443
    if ':' in url:
        port = int(url.split(':')[1])
        if port != 443:
            return False

    return True
