    # Remove spaces and split into tokens
    tokens = re.findall(r'\d+|\-?\d*\.\d+|[+\-*\/\^]|[\(\)]', expr)

    # Define precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    associativity = {'+': 'left', '-': 'left', '*': 'left', '/': 'left', '^': 'right'}

    # Function to apply an operation
    def apply_operation(operators, values):
        while operators and operators[-1] != '(':
            op = operators.pop()
            b = values.pop()
            a = values.pop()
            if op == '+':
                values.append(a + b)
            elif op == '-':
                values.append(a - b)
            elif op == '*':
                values.append(a * b)
            elif op == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                values.append(int(a / b))
            elif op == '^':
                values.append(int(a ** b))
        return values

    # Function to parse the expression
    def parse(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or token.replace('.', '', 1).isdigit():
                values.append(float(token))
            elif token in ['+', '-', '*', '/', '^']:
