from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    # Sort items by size in descending order
    sizes.sort(reverse=True)

    bins = []
    for size in sizes:
        found_bin = False
        for i, bin in enumerate(bins):
            if sum(bin) + size <= capacity:
                bin.append(size)
                found_bin = True
                break
        if not found_bin:
            bins.append([size])

    return bins
