def league_table(results: List[Tuple[str, str, int, int]]) -> List[Tuple[str, int, int, int]]:
    if not results:
        return []

    # Initialize a dictionary to store the league table data
    league_data = {}

    # Iterate through each result tuple
    for home, away, home_goals, away_goals in results:
        # Update the league data for both teams
        if home in league_data:
            league_data[home]['wins'] += 1
            league_data[home]['draws'] += 1
            league_data[home]['losses'] += 1
            league_data[home]['total_points'] += 3
            league_data[home]['goal_difference'] += home_goals - away_goals
            league_data[home]['goals_scored'] += home_goals
        else:
            league_data[home] = {'wins': 1, 'draws': 0, 'losses': 0, 'total_points': 3, 'goal_difference': home_goals - away_goals, 'goals_scored': home_goals}

        if away in league_data:
            league_data[away]['wins'] += 1
            league_data[away]['draws'] += 1
            league_data[away]['losses'] += 1
            league_data[away]['total_points'] += 3
            league_data[away]['goal_difference'] -= away_goals - home_goals
            league_data[away]['goals_scored'] += away_goals
        else:
            league_data[away] = {'wins': 1, 'draws': 0, 'losses': 0, 'total_points': 3, 'goal_difference': -away_goals + home_goals, 'goals_scored': away_goals}

    # Sort the league data based on the specified criteria
    sorted_league_data = sorted(league_data.items(), key=lambda x: (-x[1]['total_points'], -x[1]['goal_difference'], -x[1]['goals_scored'], x[0]))

    # Convert the sorted data back to a list of tuples
    final_table = [(team, points, goal_difference, goals_scored) for team, data in sorted_league_data]

    return final_table

