            team_scores[away] = 3 if away_goals > home_goals else (1 if away_goals == home_goals else 0)

    # Create a list of tuples with team names, points, goal difference, and goals scored
    league_table_data = [(team, team_scores[team], abs(home_goals - away_goals), home_goals) for team in team_scores]

    # Sort the league table data based on the specified criteria
    league_table_data.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

