def evaluate_formula(formula: str, x: float) -> float:
    # Define a dictionary to map function names to their corresponding functions
    functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Split the formula into tokens
    tokens = formula.replace(' ', '').split()

    # Initialize the stack for operators and operands
    operator_stack = []
    operand_stack = []

    # Iterate over each token in the formula
    for token in tokens:
        if token.isdigit():
            operand_stack.append(float(token))
        elif token in functions:
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack[-1] != '(':
                apply_operator(operand_stack, operator_stack.pop())
            operator_stack.pop()  # Remove the '(' from the stack
        else:
            raise ValueError("Invalid character in formula")

    # Apply any remaining operators on the operands
    while operator_stack:
        apply_operator(operand_stack, operator_stack.pop())

    # The final result should be the only element left in the operand stack
    return operand_stack[0]

