        operands.append(operands.pop() + operands.pop())
    elif operator == '-':
        operands.append(-operands.pop() + operands.pop())
    elif operator == '*':
        operands.append(operands.pop() * operands.pop())
    elif operator == '/':
        divisor = operands.pop()
        if divisor == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        operands.append(operands.pop() / divisor)
    elif operator == '**':
        operands.append(operands.pop() ** operands.pop())

