import math

def evaluate_formula(formula: str, x: float) -> float:
    # Define the allowed functions and their arguments
    functions = {
        'sqrt': lambda y: math.sqrt(y),
        'abs': lambda y: abs(y),
        'sin': lambda y: math.sin(math.radians(y)),
        'cos': lambda y: math.cos(math.radians(y))
    }

    # Helper function to parse and evaluate the formula
    def parse_and_evaluate(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token.isalpha() and token != 'x':
                raise ValueError("Invalid variable name")
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    operator = stack.pop()
                    right = stack.pop()
                    left = stack.pop()
                    if operator == '+':
                        stack.append(left + right)
                    elif operator == '-':
                        stack.append(left - right)
                    elif operator == '*':
                        stack.append(left * right)
                    elif operator == '/':
                        if right == 0:
                            raise ZeroDivisionError("Division by zero")
                        stack.append(left / right)
                    elif operator == '**':
                        stack.append(left ** right)
                stack.pop()  # Remove the '('
            else:
                if token in functions:
                    stack.append(functions[token](stack.pop()))
                else:
                    raise ValueError(f"Unknown function: {token}")

        if len(stack) != 1:
            raise ValueError("Invalid formula")
        return stack[0]

    # Split the formula into tokens
    tokens = formula.replace(' ', '').split()

    # Parse and evaluate the formula
    result = parse_and_evaluate(tokens)

    # Substitute the value of x into the result
    return result
