    operator_pattern = r"[+\-*/^]"
    parenthesis_pattern = r"\([^()]*\)"

    # Initialize the stack for operators and operands
    operators = []
    operands = []

    # Iterate over each character in the expression
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            # Extract numbers until a non-digit is found
            num_str = ""
            while i < len(expr) and expr[i].isdigit():
                num_str += expr[i]
                i += 1
            operands.append(int(num_str))
        elif expr[i] == '(':
            # Push the index onto the stack
            operators.append(i)
            i += 1
        elif expr[i] == ')':
            # Pop operators and operands until the corresponding '(' is found
            start = operators.pop()
            sub_expr = expr[start + 1:i]
            result = evaluate_expression(sub_expr)
            operands.append(result)
            i += 1
        elif expr[i] in "+-*/^":
            # Handle unary minus
            if expr[i] == '-' and i > 0 and expr[i - 1] in "+-*/^":
                continue
            # Pop operators and operands until the higher precedence operator is found
            while operators and operators[-1] != '(' and precedence(operators[-1]) >= precedence(expr[i]):
                op = operators.pop()
                b = operands.pop()
                a = operands.pop()
                if op == '+':
                    operands.append(a + b)
                elif op == '-':
                    operands.append(a - b)
                elif op == '*':
