                elif op == '/':
                    operands.append(a // b)
                elif op == '^':
                    operands.append(a ** b)
            # Push the current operator onto the stack
            operators.append(expr[i])
            i += 1
        else:
            raise ValueError(f"Invalid character '{expr[i]}' in expression")

    # Pop any remaining operators and operands
    while operators:
        op = operators.pop()
        b = operands.pop()
        a = operands.pop()
