from typing import List

def min_slides(grid: List[str]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    # Find the positions of S and E
    start_pos = None
    end_pos = None

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_pos = (i, j)
            elif grid[i][j] == 'E':
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        return -1  # No start or end position found

    def is_valid_move(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] != '#'

    def dfs(x, y, steps):
        if (x, y) == end_pos:
            return steps

        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny):
                return dfs(nx, ny, steps + 1)

        return float('inf')

    min_steps = float('inf')
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.':
                min_steps = min(min_steps, dfs(i, j, 0))

    return min_steps if min_steps != float('inf') else -1
