import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define a regular expression pattern for matching numbers, operators, and parentheses
    pattern = r"(\d+\.\d+|\d+|[+-*/^()])"

    # Find all matches in the expression
    tokens = re.findall(pattern, expr)

    # Initialize the stack for operators and operands
    stack = []
    operators = {'+', '-', '*', '/', '^'}

    # Iterate over each token
    for token in tokens:
        if token.isdigit():
            # If the token is a number, push it onto the stack
            stack.append(int(token))
        elif token == '(':
            # If the token is an opening parenthesis, push it onto the stack
            stack.append(token)
        elif token == ')':
            # If the token is a closing parenthesis, pop operators from the stack until an opening parenthesis is found
            while stack[-1] != '(':
                op = stack.pop()
                b = stack.pop()
                a = stack.pop()
                if op == '+':
                    stack.append(a + b)
                elif op == '-':
                    stack.append(a - b)
                elif op == '*':
                    stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Cannot divide by zero")
                    stack.append(a // b)
                elif op == '^':
                    stack.append(a ** b)
            # Pop the opening parenthesis from the stack
            stack.pop()
        elif token in operators:
            # If the token is an operator, pop two operands from the stack, apply the operator, and push the result back onto the stack
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Cannot divide by zero")
                stack.append(a // b)
            elif token == '^':
                stack.append(a ** b)

    # The final result will be the only element left on the stack
    return stack[0]
