def evaluate_expression(expr: str) -> int:
    # Remove spaces and split the expression into tokens
    tokens = re.findall(r'\d+|\+|-|\*|\/|\^|\(|\)', expr.replace(' ', ''))

    # Define helper functions for each operator
    def add(a, b):
        return a + b

    def subtract(a, b):
        return a - b

    def multiply(a, b):
        return a * b

    def divide(a, b):
        if b == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        return a // b

    def power(a, b):
        return a ** b

    # Map token strings to their corresponding functions
    ops = {
        '+': add,
        '-': subtract,
        '*': multiply,
        '/': divide,
        '^': power
    }

    # Evaluate the expression using a stack-based approach
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token in ops:
            op = ops[token]
            b = stack.pop()
