def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0

    def execute_instruction(instruction):
        nonlocal stack, ip
        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            stack.append(int(parts[1]))
        elif opcode == 'POP':
            if not stack:
                return None
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif opcode == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif opcode == 'MUL':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif opcode == 'JMP':
            t = int(parts[1])
            if t >= len(program):
                return None
            ip = t
        elif opcode == 'JZ':
            t = int(parts[1])
            if stack and stack[-1] == 0:
                ip = t
            else:
                ip += 1
        else:
            return None

    for _ in range(1000):
        if ip >= len(program):
            break
        execute_instruction(program[ip])
        ip += 1

    return stack
