from typing import List

def run_stack_machine(program: List[str]) -> List[int]:
    stack = []
    ip = 0

    while ip < len(program):
        instruction = program[ip]

        if instruction.startswith('PUSH'):
            _, num_str = instruction.split()
            stack.append(int(num_str))
        elif instruction == 'POP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("Not enough elements for swap")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith('ADD'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for addition")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for subtraction")
            a, b = stack.pop(), stack.pop()
            stack.append(b - a)
        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                raise ValueError("Not enough elements for multiplication")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif instruction == 'JMP':
            _, target_index = instruction.split()
            ip = int(target_index)
        elif instruction == 'JZ':
            _, target_index = instruction.split()
            if stack[-1] == 0:
                ip = int(target_index)
            else:
                ip += 1
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        if ip >= len(program):
            break

        ip += 1

    if ip >= len(program):
        raise RuntimeError("Program execution exceeded limit")

    return stack
