def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    def validate_operation(operation):
        account, *args = operation
        if account not in balances:
            return False
        if args[1] <= 0:
            return False
        if operation == ('deposit', account, args[1]):
            if balances[account] >= args[1]:
                balances[account] += args[1]
            else:
                return False
        elif operation == ('withdraw', account, args[1]):
            if balances[account] >= args[1]:
                balances[account] -= args[1]
            else:
                return False
        elif operation == ('transfer', account, target, args[1]):
            if balances[account] >= args[1] + 2:
                balances[account] -= args[1] + 2
                balances[target] += args[1]
            else:
                return False
        elif operation == ('freeze', account):
            if balances[account] > 0:
                balances[account] = 0
            else:
                return False
        elif operation == ('unfreeze', account):
            if balances[account] == 0:
                balances[account] = 1
            else:
                return False
        return True

    for i, op in enumerate(ops):
        if not validate_operation(op):
            failed.append(i)

    return final_balances, failed
